class Solution {
public:
    int removeOnes(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int initial = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) initial |= (1 << (r * n + c));
            }
        }
        if (initial == 0) return 0;
        queue<pair<int, int>> q;
        q.push({initial, 0});
        vector<bool> visited(1 << (m * n), false);
        visited[initial] = true;
        while (!q.empty()) {
            auto [state, steps] = q.front();
            q.pop();
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if ((state >> (r * n + c)) & 1) {
                        int nextState = state;
                        for (int col = 0; col < n; col++) nextState &= ~(1 << (r * n + col));
                        for (int row = 0; row < m; row++) nextState &= ~(1 << (row * n + c));
                        if (nextState == 0) return steps + 1;
                        if (!visited[nextState]) {
                            visited[nextState] = true;
                            q.push({nextState, steps + 1});
                        }
                    }
                }
            }
        }
        return 0;
    }
};

class Solution {
    public int removeOnes(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int initial = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) initial |= (1 << (r * n + c));
            }
        }
        if (initial == 0) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{initial, 0});
        boolean[] visited = new boolean[1 << (m * n)];
        visited[initial] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int state = cur[0], steps = cur[1];
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (((state >> (r * n + c)) & 1) == 1) {
